class Solution {
public:
    vector<bool> checkArithmeticSubarrays(vector<int>& nums, vector<int>& l, vector<int>& r) {
        int m = l.size();
        vector<bool> ans(m);
        for (int q = 0; q < m; q++) {
            int lo = l[q], hi = r[q];
            int mn = nums[lo], mx = nums[lo];
            for (int i = lo; i <= hi; i++) {
                if (nums[i] < mn) mn = nums[i];
                if (nums[i] > mx) mx = nums[i];
            }
            if (mn == mx) {
                ans[q] = true;
                continue;
            }
            int len = hi - lo + 1;
            int diff = mx - mn;
            if (diff % (len - 1) != 0) {
                ans[q] = false;
                continue;
            }
            int d = diff / (len - 1);
            unordered_set<int> seen;
            seen.reserve(len);
            bool ok = true;
            for (int i = lo; i <= hi; i++) {
                int val = nums[i] - mn;
                if (val % d != 0) {
                    ok = false;
                    break;
                }
                int idx = val / d;
                if (seen.count(idx)) {
                    ok = false;
                    break;
                }
                seen.insert(idx);
            }
            ans[q] = ok;
        }
        return ans;
    }
};
